                db.days ||= {};
                db.days[currentDay] ||= {notes:'',phrases:[],tools:[],video:'',checkedParts:{}};
                db.days[currentDay].phrases ||= [];
                if (!db.days[currentDay].phrases.includes(id)) db.days[currentDay].phrases.push(id);
