    const esc = value => {
        try { return escapeCustomHtml(String(value ?? '')); }
        catch { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
    };
