        item.steps=Array.isArray(item.steps)?item.steps.map(x=>typeof x==='string'?{id:uid('step'),title:'',text:x}:{id:x.id||uid('step'),title:String(x.title||''),text:String(x.text||x.instruction||'')}):[];
