        modal._themeBackgroundSvgs=[];modal._themeHoverSounds=[];modal._themeIntroAudio='';modal._themeIntroAudioName='';modal._themeAudioProjectPath='';modal._themeArtworkSnapshotV69=[];modal._themeArtworkKeyV69='';
