    const earned=component.rewardsV749.filter(reward=>reward.xp<=amount&&!claimed.has(reward.id));
    if(!earned.length)return;
    earned.forEach(reward=>claimed.add(reward.id)); component.claimedRewardIdsV749=[...claimed];
    saveDb();
